func (s *Store) GetDataset(name, version string) (*Dataset, error) {
        s.mu.RLock()
        defer s.mu.RUnlock()

        key := fmt.Sprintf("%s:%s", name, version)
        ds, ok := s.data.Datasets[key]
        if !ok {
                return nil, fmt.Errorf("dataset not found: %s", key)
        }
        return ds, nil
}

func (s *Store) ListDatasets() []*Dataset {
        s.mu.RLock()
        defer s.mu.RUnlock()

        var result []*Dataset
        for _, ds := range s.data.Datasets {
                result = append(result, ds)
        }
        return result
}
